import type {
  WorkspaceLayoutOwner,
  WorkspacePersistedLayout,
  WorkspaceResolvedLayout,
  WorkspaceScope,
} from "./types";

const STORAGE_VERSION = "v1";
const STORAGE_NAMESPACE = "hbx:workspace-layout";

export interface WorkspaceLayoutAdapter {
  resolve(scope: WorkspaceScope): WorkspaceResolvedLayout;
  save(scope: WorkspaceScope, payload: WorkspacePersistedLayout): void;
  clear(scope: WorkspaceScope, owner: WorkspaceLayoutOwner): void;
}

function normalizeStorageToken(value: string | number | null | undefined, fallback: string) {
  const token = String(value ?? "").trim();
  return token || fallback;
}

function buildStorageKey(scope: WorkspaceScope, owner: WorkspaceLayoutOwner) {
  const tenantId = normalizeStorageToken(scope.tenantId, "tenant-default");
  const moduleKey = normalizeStorageToken(scope.moduleKey, "workspace");
  const role = normalizeStorageToken(scope.role, "USER").toUpperCase();
  const userId = owner === "user" ? normalizeStorageToken(scope.userId, "anonymous") : "shared";
  return [STORAGE_NAMESPACE, STORAGE_VERSION, tenantId, moduleKey, role, owner, userId].join(":");
}

function readStorage(key: string): WorkspacePersistedLayout | null {
  if (typeof window === "undefined") return null;
  try {
    const raw = window.localStorage.getItem(key);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as WorkspacePersistedLayout;
    if (parsed?.schemaVersion !== 1 || !parsed.layout) return null;
    return parsed;
  } catch {
    return null;
  }
}

export class LocalStorageWorkspaceLayoutAdapter implements WorkspaceLayoutAdapter {
  resolve(scope: WorkspaceScope): WorkspaceResolvedLayout {
    const userLayout = readStorage(buildStorageKey(scope, "user"));
    if (userLayout) {
      return { source: "user", density: userLayout.density, layout: userLayout.layout };
    }

    const globalLayout = readStorage(buildStorageKey(scope, "global"));
    if (globalLayout) {
      return { source: "global", density: globalLayout.density, layout: globalLayout.layout };
    }

    return { source: "default", density: "cozy" };
  }

  save(scope: WorkspaceScope, payload: WorkspacePersistedLayout) {
    if (typeof window === "undefined") return;
    try {
      window.localStorage.setItem(buildStorageKey(scope, payload.owner), JSON.stringify(payload));
    } catch {
      // ignore quota or privacy errors for temporary local persistence
    }
  }

  clear(scope: WorkspaceScope, owner: WorkspaceLayoutOwner) {
    if (typeof window === "undefined") return;
    try {
      window.localStorage.removeItem(buildStorageKey(scope, owner));
    } catch {
      // ignore
    }
  }
}
