"use client";

import { createContext, useContext } from "react";
import type { DockviewApi } from "dockview";
import type {
  WorkspaceDensity,
  WorkspaceLayoutSource,
  WorkspacePanelDescriptor,
  WorkspaceScope,
} from "./types";

export type WorkspaceContextValue = {
  api: DockviewApi | null;
  scope: WorkspaceScope;
  density: WorkspaceDensity;
  setDensity: (density: WorkspaceDensity) => void;
  editMode: boolean;
  setEditMode: (value: boolean) => void;
  layoutSource: WorkspaceLayoutSource;
  canEdit: boolean;
  isReady: boolean;
  panels: WorkspacePanelDescriptor[];
  openPanel: (panelId: string) => void;
  closePanel: (panelId: string) => void;
  saveUserLayout: () => void;
  publishGlobalLayout: () => void;
  resetUserLayout: () => void;
  restoreModuleDefault: () => void;
  clearGlobalLayout: () => void;
};

const WorkspaceContext = createContext<WorkspaceContextValue | null>(null);

export function WorkspaceProvider({
  value,
  children,
}: {
  value: WorkspaceContextValue;
  children: React.ReactNode;
}) {
  return <WorkspaceContext.Provider value={value}>{children}</WorkspaceContext.Provider>;
}

export function useWorkspace() {
  const context = useContext(WorkspaceContext);
  if (!context) {
    throw new Error("useWorkspace must be used inside WorkspaceProvider");
  }
  return context;
}
