"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  DockviewReact,
  type AddPanelOptions,
  type DockviewApi,
  type DockviewReadyEvent,
} from "dockview";
import { WorkspaceProvider } from "./WorkspaceContext";
import { LocalStorageWorkspaceLayoutAdapter } from "./storage";
import type {
  WorkspaceComponents,
  WorkspaceDefaultLayoutFactory,
  WorkspaceDensity,
  WorkspaceLayoutOwner,
  WorkspaceLayoutSource,
  WorkspacePanelDescriptor,
  WorkspaceScope,
} from "./types";

type WorkspaceShellProps = {
  moduleLabel: string;
  scope: WorkspaceScope;
  components: WorkspaceComponents;
  panels: WorkspacePanelDescriptor[];
  createDefaultLayout: WorkspaceDefaultLayoutFactory;
  className?: string;
  toolbarSlot?: React.ReactNode;
};

const DENSITY_OPTIONS: Array<{ value: WorkspaceDensity; label: string }> = [
  { value: "compact", label: "Compacto" },
  { value: "cozy", label: "Padrão" },
  { value: "comfortable", label: "Confortável" },
];

function buildPersistedLayout(
  api: DockviewApi,
  scope: WorkspaceScope,
  density: WorkspaceDensity,
  owner: WorkspaceLayoutOwner,
) {
  return {
    schemaVersion: 1 as const,
    owner,
    moduleKey: scope.moduleKey,
    tenantId: scope.tenantId,
    role: scope.role,
    userId: scope.userId,
    density,
    updatedAt: new Date().toISOString(),
    layout: api.toJSON(),
  };
}

export default function WorkspaceShell({
  moduleLabel,
  scope,
  components,
  panels,
  createDefaultLayout,
  className,
  toolbarSlot,
}: WorkspaceShellProps) {
  const adapterRef = useRef(new LocalStorageWorkspaceLayoutAdapter());
  const apiRef = useRef<DockviewApi | null>(null);
  const saveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const hydratingRef = useRef(false);
  const readyRef = useRef(false);

  const [api, setApi] = useState<DockviewApi | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [density, setDensity] = useState<WorkspaceDensity>("cozy");
  const [layoutSource, setLayoutSource] = useState<WorkspaceLayoutSource>("default");

  const normalizedRole = String(scope.role || "").trim().toUpperCase();
  const canEdit = Boolean(scope.isMaster || normalizedRole === "GERENTE");
  const canPublishGlobal = Boolean(scope.isMaster);
  const panelsById = useMemo(
    () => Object.fromEntries(panels.map((panel) => [panel.id, panel])) as Record<string, WorkspacePanelDescriptor>,
    [panels],
  );

  const applyDefaultLayout = useCallback(
    (targetApi: DockviewApi) => {
      hydratingRef.current = true;
      targetApi.clear();
      createDefaultLayout(targetApi, panelsById);
      hydratingRef.current = false;
      setLayoutSource("default");
    },
    [createDefaultLayout, panelsById],
  );

  const persistUserLayout = useCallback(() => {
    if (!apiRef.current) return;
    const payload = buildPersistedLayout(apiRef.current, scope, density, "user");
    adapterRef.current.save(scope, payload);
    setLayoutSource("user");
  }, [density, scope]);

  const persistGlobalLayout = useCallback(() => {
    if (!apiRef.current || !canPublishGlobal) return;
    const payload = buildPersistedLayout(apiRef.current, scope, density, "global");
    adapterRef.current.save(scope, payload);
    setLayoutSource("global");
  }, [canPublishGlobal, density, scope]);

  const scheduleUserSave = useCallback(() => {
    if (saveTimerRef.current) clearTimeout(saveTimerRef.current);
    saveTimerRef.current = setTimeout(() => {
      persistUserLayout();
    }, 300);
  }, [persistUserLayout]);

  const resolveInitialLayout = useCallback(
    (targetApi: DockviewApi) => {
      const resolved = adapterRef.current.resolve(scope);
      setDensity(resolved.density);

      if (resolved.layout) {
        hydratingRef.current = true;
        try {
          targetApi.fromJSON(resolved.layout, { reuseExistingPanels: false });
          setLayoutSource(resolved.source);
        } catch {
          applyDefaultLayout(targetApi);
        } finally {
          hydratingRef.current = false;
        }
      } else {
        applyDefaultLayout(targetApi);
      }
    },
    [applyDefaultLayout, scope],
  );

  const handleReady = useCallback(
    (event: DockviewReadyEvent) => {
      apiRef.current = event.api;
      setApi(event.api);
      resolveInitialLayout(event.api);
      readyRef.current = true;
      setIsReady(true);
    },
    [resolveInitialLayout],
  );

  useEffect(() => {
    if (!api) return;
    const disposable = api.onDidLayoutChange(() => {
      if (!readyRef.current || hydratingRef.current) return;
      scheduleUserSave();
    });
    return () => disposable.dispose();
  }, [api, scheduleUserSave]);

  useEffect(() => {
    if (!api || !readyRef.current || hydratingRef.current) return;
    persistUserLayout();
  }, [api, density, persistUserLayout]);

  useEffect(() => {
    return () => {
      if (saveTimerRef.current) clearTimeout(saveTimerRef.current);
    };
  }, []);

  const openPanel = useCallback(
    (panelId: string) => {
      const targetApi = apiRef.current;
      const descriptor = panelsById[panelId];
      if (!targetApi || !descriptor) return;

      const existing = targetApi.getPanel(descriptor.id);
      if (existing) {
        existing.api.setActive();
        return;
      }

      const baseOptions = {
        id: descriptor.id,
        title: descriptor.title,
        component: descriptor.component,
        tabComponent: descriptor.tabComponent,
        params: descriptor.params,
        minimumHeight: descriptor.minimumHeight,
        minimumWidth: descriptor.minimumWidth,
        maximumHeight: descriptor.maximumHeight,
        maximumWidth: descriptor.maximumWidth,
        initialHeight: descriptor.initialHeight,
        initialWidth: descriptor.initialWidth,
      };

      if (targetApi.totalPanels === 0) {
        targetApi.addPanel(baseOptions as AddPanelOptions);
        return;
      }

      const referencePanel = targetApi.activePanel ?? targetApi.panels[0];
      if (!referencePanel) {
        targetApi.addPanel(baseOptions as AddPanelOptions);
        return;
      }

      targetApi.addPanel({
        ...baseOptions,
        position: { referencePanel },
      } as AddPanelOptions);
    },
    [panelsById],
  );

  const closePanel = useCallback((panelId: string) => {
    const targetApi = apiRef.current;
    if (!targetApi) return;
    const panel = targetApi.getPanel(panelId);
    if (!panel) return;
    targetApi.removePanel(panel);
  }, []);

  const resetUserLayout = useCallback(() => {
    adapterRef.current.clear(scope, "user");
    const targetApi = apiRef.current;
    if (!targetApi) return;
    const resolved = adapterRef.current.resolve(scope);
    setDensity(resolved.density);
    if (resolved.layout) {
      hydratingRef.current = true;
      targetApi.fromJSON(resolved.layout, { reuseExistingPanels: false });
      hydratingRef.current = false;
      setLayoutSource(resolved.source);
      return;
    }
    applyDefaultLayout(targetApi);
  }, [applyDefaultLayout, scope]);

  const restoreModuleDefault = useCallback(() => {
    adapterRef.current.clear(scope, "user");
    if (canPublishGlobal) {
      adapterRef.current.clear(scope, "global");
    }
    setDensity("cozy");
    const targetApi = apiRef.current;
    if (!targetApi) return;
    applyDefaultLayout(targetApi);
  }, [applyDefaultLayout, canPublishGlobal, scope]);

  const clearGlobalLayout = useCallback(() => {
    if (!canPublishGlobal) return;
    adapterRef.current.clear(scope, "global");
    setLayoutSource("default");
  }, [canPublishGlobal, scope]);

  const contextValue = useMemo(
    () => ({
      api,
      scope,
      density,
      setDensity,
      editMode,
      setEditMode,
      layoutSource,
      canEdit,
      isReady,
      panels,
      openPanel,
      closePanel,
      saveUserLayout: persistUserLayout,
      publishGlobalLayout: persistGlobalLayout,
      resetUserLayout,
      restoreModuleDefault,
      clearGlobalLayout,
    }),
    [
      api,
      canEdit,
      closePanel,
      density,
      editMode,
      isReady,
      layoutSource,
      openPanel,
      panels,
      persistGlobalLayout,
      persistUserLayout,
      resetUserLayout,
      restoreModuleDefault,
      clearGlobalLayout,
      scope,
    ],
  );

  return (
    <WorkspaceProvider value={contextValue}>
      <section
        className={`hbx-workspace ${className || ""}`.trim()}
        data-density={density}
        data-edit-mode={editMode ? "true" : "false"}
      >
        <header className="hbx-workspace__toolbar">
          <div className="hbx-workspace__toolbar-copy">
            <p className="hbx-workspace__eyebrow">Workspace dockável</p>
            <h3>{moduleLabel}</h3>
            <span className="hbx-workspace__source">Origem: {layoutSource}</span>
          </div>

          <div className="hbx-workspace__toolbar-actions">
            <div className="hbx-workspace__panel-shortcuts">
              {panels.map((panel) => {
                const panelOpen = Boolean(api?.getPanel(panel.id));
                return (
                  <button
                    key={panel.id}
                    type="button"
                    className={`hbx-workspace__chip ${panelOpen ? "is-open" : ""}`}
                    onClick={() => openPanel(panel.id)}
                    title={panel.description}
                  >
                    {panel.title}
                  </button>
                );
              })}
            </div>

            <label className="hbx-workspace__density">
              <span>Densidade</span>
              <select value={density} onChange={(event) => setDensity(event.target.value as WorkspaceDensity)}>
                {DENSITY_OPTIONS.map((option) => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
            </label>

            {toolbarSlot}

            {canEdit ? (
              <button
                type="button"
                className={`btn btn-sm ${editMode ? "btn-primary" : "btn-secondary"}`}
                onClick={() => setEditMode((current) => !current)}
              >
                {editMode ? "Sair do modo edição" : "Modo edição"}
              </button>
            ) : null}

            <button type="button" className="btn btn-secondary btn-sm" onClick={resetUserLayout}>
              Restaurar meu layout
            </button>

            {canEdit ? (
              <button type="button" className="btn btn-secondary btn-sm" onClick={persistUserLayout}>
                Salvar rascunho
              </button>
            ) : null}

            {canPublishGlobal ? (
              <>
                <button type="button" className="btn btn-primary btn-sm" onClick={persistGlobalLayout}>
                  Publicar global
                </button>
                <button type="button" className="btn btn-secondary btn-sm" onClick={clearGlobalLayout}>
                  Limpar global
                </button>
                <button type="button" className="btn btn-danger btn-sm" onClick={restoreModuleDefault}>
                  Padrão do módulo
                </button>
              </>
            ) : null}
          </div>
        </header>

        <div className="hbx-workspace__canvas dockview-theme-replit">
          <DockviewReact
            className="hbx-workspace__dockview"
            components={components}
            onReady={handleReady}
            disableDnd={!editMode}
            locked={!editMode}
            dndEdges={editMode ? undefined : false}
            noPanelsOverlay="emptyGroup"
            disableFloatingGroups
            hideBorders
            singleTabMode="fullwidth"
          />
        </div>
      </section>
    </WorkspaceProvider>
  );
}